const AIRPORT_RE = /\b(airport|intl|international|terminal|dfw|dal|jfk|lga|ewr|lax|sfo|ord|mia|las|iah|hou|aus|atl|dxb|lhr)\b/i;
const isAirport = (s = "") => AIRPORT_RE.test(s);
const tripIsAirport = (t) => isAirport(t.pickup) || (t.type === "One-way" && isAirport(t.dropoff));

function priceFor(c, t) {
  if (t && t.type === "By the hour") {
    const hrs = Math.max(2, Math.min(24, Number(t.duration) || 2));
    const base = c.hr * hrs;
    const sur = +(base * 0.166).toFixed(2);
    return { base, sur, total: +(base + sur).toFixed(2), hrs, dist: 0 };
  }
  if (t && t.dist != null) {
    const fare = +(c.book + c.mi * t.dist).toFixed(2);
    const sur = +(fare * 0.166).toFixed(2);
    return { base: fare, sur, total: +(fare + sur).toFixed(2), hrs: 0, dist: t.dist };
  }
  return { base: c.base, sur: c.sur, total: +(c.base + c.sur).toFixed(2), hrs: 0, dist: null };
}

const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
const WK = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
function fmtDate(v) {
  if (!v) return "Select date";
  const d = new Date(v + "T00:00:00");
  if (isNaN(d.getTime())) return v;
  return `${WK[d.getDay()]}, ${d.getDate()} ${MONTHS[d.getMonth()]} ${d.getFullYear()}`;
}
function fmtTime(v) {
  if (!v) return "Select time";
  const p = String(v).split(":");
  const h = Number(p[0]), m = Number(p[1]);
  if (isNaN(h)) return v;
  const ap = h >= 12 ? "pm" : "am";
  const hh = ((h + 11) % 12) + 1;
  return `${hh}:${String(isNaN(m) ? 0 : m).padStart(2, "0")} ${ap}`;
}

function haversineMiles(a, b) {
  const R = 3958.8, rad = (d) => (d * Math.PI) / 180;
  const dLat = rad(b.lat - a.lat), dLon = rad(b.lon - a.lon);
  const s = Math.sin(dLat / 2) ** 2 + Math.cos(rad(a.lat)) * Math.cos(rad(b.lat)) * Math.sin(dLon / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(s), Math.sqrt(1 - s));
}
