function searchPlaces(q) {
  if (!q) return [];
  const s = q.trim().toLowerCase();
  if (!s) return [];
  return PLACES.filter((p) => p.name.toLowerCase().includes(s)).slice(0, 6).map((p) => ({ label: p.name, lat: p.lat, lon: p.lon }));
}

async function geocode(q) {
  const local = searchPlaces(q);
  if (local.length) return local;
  if (!q || q.trim().length < 3) return [];
  if (ORS_KEY) {
    try {
      const r = await fetch(`https://api.openrouteservice.org/geocode/autocomplete?api_key=${ORS_KEY}&text=${encodeURIComponent(q)}&size=6`);
      const j = await r.json();
      const fs = (j && j.features) || [];
      if (fs.length) return fs.map((ft) => ({ label: ft.properties.label, lat: ft.geometry.coordinates[1], lon: ft.geometry.coordinates[0] }));
    } catch (e) {}
  }
  try {
    const r = await fetch(`https://nominatim.openstreetmap.org/search?format=jsonv2&limit=5&q=${encodeURIComponent(q)}`, { headers: { Accept: "application/json" } });
    const j = await r.json();
    return (j || []).map((d) => ({ label: d.display_name, lat: +d.lat, lon: +d.lon }));
  } catch (e) { return []; }
}
async function osrmRoute(a, b) {
  if (ORS_KEY) {
    try {
      const r = await fetch(`https://api.openrouteservice.org/v2/directions/driving-car?api_key=${ORS_KEY}&start=${a.lon},${a.lat}&end=${b.lon},${b.lat}`);
      const j = await r.json();
      const ft = j && j.features && j.features[0];
      if (ft) {
        const sum = ft.properties.summary;
        return { miles: +(sum.distance / 1609.34).toFixed(1), mins: Math.round(sum.duration / 60), geometry: ft.geometry.coordinates };
      }
    } catch (e) {}
  }
  try {
    const r = await fetch(`https://router.project-osrm.org/route/v1/driving/${a.lon},${a.lat};${b.lon},${b.lat}?overview=full&geometries=geojson`);
    const j = await r.json();
    const rt = j && j.routes && j.routes[0];
    if (rt) return { miles: +(rt.distance / 1609.34).toFixed(1), mins: Math.round(rt.duration / 60), geometry: rt.geometry.coordinates };
  } catch (e) {}
  const m = +(haversineMiles(a, b) * 1.3).toFixed(1);
  return { miles: m, mins: Math.max(1, Math.round(m * 2)), geometry: null };
}
let _mlPromise = null;
function loadMapLibre() {
  if (typeof window !== "undefined" && window.maplibregl) return Promise.resolve(window.maplibregl);
  if (_mlPromise) return _mlPromise;
  _mlPromise = new Promise((res, rej) => {
    const css = document.createElement("link");
    css.rel = "stylesheet";
    css.href = "https://cdnjs.cloudflare.com/ajax/libs/maplibre-gl/4.7.1/maplibre-gl.css";
    document.head.appendChild(css);
    const sc = document.createElement("script");
    sc.src = "https://cdnjs.cloudflare.com/ajax/libs/maplibre-gl/4.7.1/maplibre-gl.js";
    sc.onload = () => res(window.maplibregl);
    sc.onerror = rej;
    document.head.appendChild(sc);
  });
  return _mlPromise;
}

