function AddrField({ label, value, geo, onText, onPick, placeholder }) {
  const [sug, setSug] = React.useState([]);
  const [open, setOpen] = React.useState(false);
  const [busy, setBusy] = React.useState(false);
  const tRef = React.useRef(null);
  const run = (q) => {
    onText(q);
    clearTimeout(tRef.current);
    const local = searchPlaces(q);
    setSug(local);
    setOpen(local.length > 0);
    if (local.length === 0 && q.trim().length >= 4) {
      setBusy(true);
      tRef.current = setTimeout(async () => {
        const net = await geocode(q);
        setSug(net); setOpen(net.length > 0); setBusy(false);
      }, 450);
    } else {
      setBusy(false);
    }
  };
  return (
    <div style={{ position: "relative" }}>
      <div className="d-field" style={{ padding: "12px 16px", borderRadius: 12, background: C.paper, border: `1px solid ${geo ? C.blue : C.line}`, transition: "border-color .2s" }}>
        <div style={{ fontSize: 12, color: C.sub, marginBottom: 3, letterSpacing: ".02em" }}>{label}</div>
        <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
          <Ico name="pin" size={17} color={geo ? C.blue : C.sub} />
          <input value={value} placeholder={placeholder} onChange={(e) => run(e.target.value)} onFocus={() => sug.length && setOpen(true)} onBlur={() => setTimeout(() => setOpen(false), 180)}
            style={{ border: "none", background: "transparent", fontSize: 15, color: C.ink, fontFamily: SANS, width: "100%" }} />
          {busy && <span style={{ fontSize: 12, color: C.sub }}>…</span>}
        </div>
      </div>
      {open && sug.length > 0 && (
        <div style={{ position: "absolute", top: "100%", left: 0, right: 0, zIndex: 60, marginTop: 6, background: C.panel, border: `1px solid ${C.line}`, borderRadius: 12, boxShadow: "0 22px 54px -26px rgba(0,0,0,.45)", overflow: "hidden", maxHeight: 240, overflowY: "auto" }}>
          {sug.map((sg, i) => (
            <button key={i} onMouseDown={(e) => { e.preventDefault(); onPick(sg); setOpen(false); setSug([]); }}
              style={{ display: "flex", gap: 10, width: "100%", textAlign: "left", border: "none", borderTop: i ? `1px solid ${C.line}` : "none", background: "transparent", cursor: "pointer", padding: "12px 14px", fontFamily: SANS, fontSize: 13.5, color: C.ink, lineHeight: 1.35 }}>
              <span style={{ flex: "0 0 auto", marginTop: 1 }}><Ico name="pin" size={15} color={C.sub} /></span>
              <span>{sg.label}</span>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

function OfflineRouteSVG({ trip }) {
  const a = trip.pickupGeo, b = trip.dropoffGeo;
  const W = 600, H = 560, pad = 96;
  let ax = W / 2, ay = H / 2 - 70, bx = W / 2, by = H / 2 + 70;
  if (a && b) {
    const minLon = Math.min(a.lon, b.lon), maxLon = Math.max(a.lon, b.lon);
    const minLat = Math.min(a.lat, b.lat), maxLat = Math.max(a.lat, b.lat);
    const sx = (lon) => (maxLon === minLon ? W / 2 : pad + ((lon - minLon) / (maxLon - minLon)) * (W - 2 * pad));
    const sy = (lat) => (maxLat === minLat ? H / 2 : pad + ((maxLat - lat) / (maxLat - minLat)) * (H - 2 * pad));
    ax = sx(a.lon); ay = sy(a.lat); bx = sx(b.lon); by = sy(b.lat);
  } else if (a) {
    ax = W / 2; ay = H / 2;
  }
  return (
    <svg viewBox={`0 0 ${W} ${H}`} preserveAspectRatio="xMidYMid slice" style={{ position: "absolute", inset: 0, width: "100%", height: "100%" }}>
      <rect width={W} height={H} fill="#E8E6E1" />
      <g stroke="#DAD7CD" strokeWidth="1">
        {[1, 2, 3, 4].map((i) => <line key={"h" + i} x1="0" y1={(H * i) / 5} x2={W} y2={(H * i) / 5} />)}
        {[1, 2, 3, 4].map((i) => <line key={"v" + i} x1={(W * i) / 5} y1="0" x2={(W * i) / 5} y2={H} />)}
      </g>
      {a && b && <line x1={ax} y1={ay} x2={bx} y2={by} stroke="#4B2A78" strokeWidth="4" strokeDasharray="1 11" strokeLinecap="round" />}
      <circle cx={ax} cy={ay} r="11" fill="#fff" stroke="#4B2A78" strokeWidth="5" />
      {b && <circle cx={bx} cy={by} r="11" fill="#fff" stroke="#141413" strokeWidth="5" />}
      {trip.dist != null && (
        <g>
          <rect x={W / 2 - 84} y={H - 56} width="168" height="34" rx="17" fill="#141413" />
          <text x={W / 2} y={H - 33} textAnchor="middle" fontFamily={SANS} fontSize="15" fill="#fff">{trip.dist} mi · {trip.dur} min</text>
        </g>
      )}
    </svg>
  );
}

function RouteMap({ trip }) {
  const ref = React.useRef(null);
  const [failed, setFailed] = React.useState(false);
  const a = trip.pickupGeo, b = trip.dropoffGeo;
  React.useEffect(() => {
    let map = null, cancelled = false, loaded = false;
    const timer = setTimeout(() => { if (!loaded && !cancelled) { setFailed(true); if (map) { try { map.remove(); } catch (e) {} } } }, 4500);
    loadMapLibre().then((ml) => {
      if (cancelled || !ref.current || !ml) return;
      map = new ml.Map({ container: ref.current, style: "https://tiles.openfreemap.org/styles/liberty", center: a ? [a.lon, a.lat] : [-96.95, 32.86], zoom: a ? 11 : 9, attributionControl: false });
      map.on("load", () => {
        loaded = true; clearTimeout(timer);
        if (a) new ml.Marker({ color: "#4B2A78" }).setLngLat([a.lon, a.lat]).addTo(map);
        if (b) new ml.Marker({ color: "#141413" }).setLngLat([b.lon, b.lat]).addTo(map);
        const coords = trip.routeGeo || (a && b ? [[a.lon, a.lat], [b.lon, b.lat]] : null);
        if (coords && coords.length > 1) {
          map.addSource("rt", { type: "geojson", data: { type: "Feature", geometry: { type: "LineString", coordinates: coords } } });
          map.addLayer({ id: "rt", type: "line", layout: { "line-cap": "round", "line-join": "round" }, paint: { "line-color": "#4B2A78", "line-width": 4 } });
          const lons = coords.map((c) => c[0]), lats = coords.map((c) => c[1]);
          map.fitBounds([[Math.min(...lons), Math.min(...lats)], [Math.max(...lons), Math.max(...lats)]], { padding: 64, duration: 0 });
        }
      });
    }).catch(() => { clearTimeout(timer); if (!cancelled) setFailed(true); });
    return () => { cancelled = true; clearTimeout(timer); if (map) { try { map.remove(); } catch (e) {} } };
  }, [a?.lat, a?.lon, b?.lat, b?.lon, trip.routeGeo ? JSON.stringify(trip.routeGeo) : null]);
  if (failed) return <OfflineRouteSVG trip={trip} />;
  return <div ref={ref} style={{ position: "absolute", inset: 0 }} />;
}

function DBookingWidget({ trip, setTrip, go }) {
  const tabs = ["One-way", "By the hour"];
  const airport = tripIsAirport(trip);
  const [searching, setSearching] = React.useState(false);
  const ready = trip.pickup.trim() && (trip.type === "By the hour" ? trip.duration : trip.dropoff.trim()) && trip.date && trip.time;
  const onSearch = async () => {
    if (!ready || searching) return;
    setSearching(true);
    try {
      let a = trip.pickupGeo;
      if (!a && trip.pickup) a = (await geocode(trip.pickup))[0] || null;
      const patch = { pickupGeo: a, dist: null, dur: null, routeGeo: null };
      if (trip.type === "One-way") {
        let b = trip.dropoffGeo;
        if (!b && trip.dropoff) b = (await geocode(trip.dropoff))[0] || null;
        patch.dropoffGeo = b;
        if (a && b) {
          const r = await osrmRoute(a, b);
          patch.dist = r.miles; patch.dur = r.mins; patch.routeGeo = r.geometry;
        }
      }
      setTrip({ ...trip, ...patch });
    } finally {
      setSearching(false);
      go(2);
    }
  };
  return (
    <div style={{ flex: "0 1 380px", width: 380, maxWidth: "100%", background: C.panel, borderRadius: 20, padding: 24, boxShadow: "0 30px 70px -30px rgba(20,20,19,.5)", border: `1px solid ${C.line}` }}>
      <div style={{ display: "flex", gap: 6, background: C.paper, borderRadius: 30, padding: 5, marginBottom: 18 }}>
        {tabs.map((t) => (
          <button key={t} onClick={() => setTrip({ ...trip, type: t })}
            style={{ flex: 1, border: "none", cursor: "pointer", borderRadius: 30, padding: "9px 0", fontSize: 14, fontWeight: 600, fontFamily: SANS, background: trip.type === t ? C.panel : "transparent", color: trip.type === t ? C.ink : C.sub, boxShadow: trip.type === t ? "0 2px 8px -3px rgba(0,0,0,.25)" : "none" }}>{t}</button>
        ))}
      </div>
      <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
        <AddrField label="Pickup" value={trip.pickup} geo={trip.pickupGeo} placeholder="Address, airport, hotel…"
          onText={(v) => setTrip({ ...trip, pickup: v, pickupGeo: null, dist: null, dur: null, routeGeo: null })}
          onPick={(g) => setTrip({ ...trip, pickup: g.label, pickupGeo: g, dist: null, dur: null, routeGeo: null })} />
        {trip.type === "One-way"
          ? <AddrField label="Drop-off" value={trip.dropoff} geo={trip.dropoffGeo} placeholder="Where to?"
              onText={(v) => setTrip({ ...trip, dropoff: v, dropoffGeo: null, dist: null, dur: null, routeGeo: null })}
              onPick={(g) => setTrip({ ...trip, dropoff: g.label, dropoffGeo: g, dist: null, dur: null, routeGeo: null })} />
          : <DDuration value={trip.duration} onChange={(v) => setTrip({ ...trip, duration: v })} />}
        {airport && <DField label="Flight number" icon="plane" value={trip.flight} placeholder="e.g. AA2412 (we track delays)" onChange={(v) => setTrip({ ...trip, flight: v })} />}
        <div style={{ display: "flex", gap: 12 }}>
          <DField label="Date" icon="calendar" type="date" value={trip.date} onChange={(v) => setTrip({ ...trip, date: v })} />
          <DField label="Time" icon="clock" type="time" value={trip.time} onChange={(v) => setTrip({ ...trip, time: v })} />
        </div>
        {trip.type === "By the hour" && <div style={{ fontSize: 12, color: C.sub, display: "flex", gap: 6, alignItems: "flex-start" }}><span style={{ flex: "0 0 auto", marginTop: 1 }}><Ico name="info" size={14} color={C.sub} /></span>40 km included per hour · starts and ends in the same city</div>}
      </div>
      <div style={{ marginTop: 18 }}><PrimaryBtn onClick={onSearch} disabled={!ready || searching}>{searching ? "Finding your route…" : "Search"}</PrimaryBtn></div>
    </div>
  );
}

